export async function processQueuedAssistantForecast(runId:string,workspaceId:string,userId:string):Promise<boolean>{
 const claim=await client.begin(async tx=>{
  await q(tx,"select set_config('app.user_id',$1,true),set_config('app.workspace_id',$2,true)",[userId,workspaceId]);
  const [row]=await q(tx,"update forecast_runs set status='running',lease_until=now()+interval '2 minutes',attempts=attempts+1,error_code=null where workspace_id=$1 and user_id=$2 and id=$3 and expires_at>now() and attempts<5 and (status='queued' or status='running' and lease_until<=now()) returning id",[workspaceId,userId,runId]);
  return Boolean(row);
 });
 if(!claim)return false;
 try{return await client.begin(async tx=>{
  await q(tx,"select set_config('app.user_id',$1,true),set_config('app.workspace_id',$2,true)",[userId,workspaceId]);
  const [row]=await q(tx,'select * from forecast_runs where workspace_id=$1 and user_id=$2 and id=$3 and status=\'running\' for update',[workspaceId,userId,runId]);if(!row)return false;
  const [prefs]=await q(tx,'select * from assistant_settings where workspace_id=$1 and user_id=$2',[workspaceId,userId]);
  const [workspace]=await q(tx,'select w.id,w.owner_user_id,w.currency,w.timezone,w.kind from workspaces w join workspace_memberships m on m.workspace_id=w.id and m.user_id=$2 where w.id=$1 and w.archived_at is null',[workspaceId,userId]);
  if(!prefs||!prefs.local_forecast_enabled||Number(prefs.consent_version)!==Number(row.consent_version)||!workspace){await q(tx,"update forecast_runs set status='superseded',lease_until=null,error_code='PERMISSION_CHANGED' where workspace_id=$1 and user_id=$2 and id=$3",[workspaceId,userId,runId]);return false;}
  const snapshot=asJson(row.input_snapshot),horizon=Number(row.horizon_days),accountId=snapshot.accountId??null;
  const built=await buildForecastSources(tx,workspaceId,userId,workspace,prefs,horizon,accountId),hash=forecastInputHash(built,prefs,horizon);
  if(hash!==row.input_hash){await q(tx,"update forecast_runs set status='superseded',lease_until=null,error_code='SOURCE_CHANGED' where workspace_id=$1 and user_id=$2 and id=$3",[workspaceId,userId,runId]);return false;}
  const [duplicate]=await q(tx,"select id from forecast_runs where workspace_id=$1 and user_id=$2 and id<>$3 and as_of_date=$4 and horizon_days=$5 and consent_version=$6 and scope_hash=$7 and input_hash=$8 and status='ready' and expires_at>now() limit 1",[workspaceId,userId,runId,built.today,horizon,row.consent_version,row.scope_hash,hash]);
  if(duplicate){await q(tx,"update forecast_runs set status='superseded',lease_until=null,error_code='IDENTICAL_RUN_EXISTS' where workspace_id=$1 and user_id=$2 and id=$3",[workspaceId,userId,runId]);return false;}
  const summary={runId:row.id,asOfDate:built.today,timezone:workspace.timezone,currency:workspace.currency,horizonDays:horizon,endDate:built.end,engineVersion:'cashflow-v1',status:'ready',stale:false,coverage:built.flags.length?'incomplete':'complete_for_selected_sources',safeToSpend:built.result.safeToSpend,safeToSpendReason:built.result.safeToSpendReason,protectedAmount:built.result.protectedAmount,minimumBalance:built.result.minimumBalance,firstShortfallDate:built.result.firstShortfallDate,firstLowBalanceDate:built.result.firstLowBalanceDate,qualityFlags:built.result.qualityFlags,scenarios:['base','conservative'],assumptionCodes:['outflows_before_unreceived_inflows','conservative_excludes_unreceived_income'],history:built.history,points:built.result.points};
  await storeForecastRows(tx,workspaceId,userId,runId,workspace,built);
  await q(tx,"update forecast_runs set status='ready',summary=$4::jsonb,quality_flags=$5::jsonb,completed_at=now(),lease_until=null,error_code=null where workspace_id=$1 and user_id=$2 and id=$3",[workspaceId,userId,runId,JSON.stringify(summary),JSON.stringify(built.result.qualityFlags)]);
  built.result.accountAlerts=(built.result.accountAlerts??[]).map((alert:any)=>({...alert,accountName:built.accounts.find((account:any)=>account.id===alert.accountId)?.name??alert.accountId}));
  await createSuggestions(tx,workspaceId,userId,runId,built.result,built.events,prefs,workspace.kind,{today:built.today,horizonDays:horizon,accounts:built.accounts,qualityFlags:built.flags,workspaceProtectedAmount:String(prefs.safety_buffer)});
  await q(tx,'insert into assistant_refresh_state(workspace_id,user_id,checked_at,last_input_hash) values($1,$2,now(),$3) on conflict(workspace_id,user_id) do update set checked_at=now(),last_input_hash=excluded.last_input_hash',[workspaceId,userId,hash]);
  return true;
 });}catch(error){
  await client.begin(async tx=>{await q(tx,"select set_config('app.user_id',$1,true),set_config('app.workspace_id',$2,true)",[userId,workspaceId]);await q(tx,"update forecast_runs set status=case when attempts>=5 then 'failed' else 'queued' end,lease_until=null,error_code='PROCESSING_RETRY' where workspace_id=$1 and user_id=$2 and id=$3 and status='running'",[workspaceId,userId,runId]);});
  throw error;
 }
}

export async function recoverQueuedAssistantForecasts():Promise<void>{
 const workspaces=await client.unsafe("select id,owner_user_id from workspaces where archived_at is null order by id");
 for(const workspace of workspaces){
  const pending=await client.begin(async tx=>{await q(tx,"select set_config('app.user_id',$1,true),set_config('app.workspace_id',$2,true)",[workspace.owner_user_id,workspace.id]);return q(tx,"select id from forecast_runs where workspace_id=$1 and user_id=$2 and expires_at>now() and (status='queued' or status='running' and lease_until<=now()) and attempts<5 order by requested_at limit 50",[workspace.id,workspace.owner_user_id]);});
  for(const run of pending)try{await processQueuedAssistantForecast(run.id,workspace.id,workspace.owner_user_id);}catch(error){console.error('Queued assistant forecast recovery failed',{runId:run.id,error:error instanceof Error?error.name:'unknown'});}
 }
}

